cssCode:
.wave-wrap { height: 250vh; width: 100%; }
.wave-sticky {
  position: sticky; top: 0; height: 100vh; width: 100%;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
  perspective: 1000px;
}
#wave-canvas { position: absolute; z-index: 1; }
.wave-text {
  font-size: 50px; font-weight: 900; color: #00ffcc; font-family: sans-serif;
  transform: translateZ(-500px) rotateX(90deg); opacity: 0;
  transition: transform 0.5s ease-out, opacity 0.5s ease-out; z-index: 10;
  text-shadow: 0 0 20px rgba(0,255,204,0.8);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#02000a;';

c.innerHTML = `
  <div class="wave-wrap">
    <div class="wave-sticky">
      <canvas id="wave-canvas"></canvas>
      <div class="wave-text" id="wTxt">SECURE FUTURE</div>
    </div>
  </div>
`;

const wCvs = document.getElementById('wave-canvas');
const wCtx = wCvs.getContext('2d');
let waveW = wCvs.width = window.innerWidth;
let waveH = wCvs.height = window.innerHeight;
let wProg = 0;

function drawWave() {
  wCtx.clearRect(0,0,waveW,waveH);
  wCtx.fillStyle = 'rgba(0, 210, 255, 0.5)';

  let time = Date.now() * 0.002;
  // Scroll thi wave ni height (Amplitude) vadhe chhe
  let amp = wProg * 150; 

  for(let x=0; x<waveW; x+=10) {
    let y = waveH/2 + Math.sin(x*0.02 + time) * amp + Math.cos(x*0.01 - time) * (amp/2);
    wCtx.beginPath(); wCtx.arc(x, y, 2, 0, Math.PI*2); wCtx.fill();
  }
  requestAnimationFrame(drawWave);
}
drawWave();

const wText = document.getElementById('wTxt');
c.addEventListener('scroll', () => {
  wProg = c.scrollTop / (c.scrollHeight - c.clientHeight);

  if(wProg > 0.7) {
    wText.style.transform = `translateZ(50px) rotateX(0deg)`;
    wText.style.opacity = 1;
  } else {
    wText.style.transform = `translateZ(-500px) rotateX(90deg)`;
    wText.style.opacity = 0;
  }
});
